mapper.select:
	  	SELECT ctrl_cmd_exec_code_id,
	  		ctrl_cmd_exec_code_name,
	  		ctrl_kind_code,
	  		ctrl_cmd_code,
	  		ctrl_exec_param,
	  		ctrl_exec_desc

		FROM ctrl_cmd_exec_code_info
  		WHERE 1=1	

  			 AND ctrl_cmd_exec_code_id = #{ctrlCmdExecCodeId}


  		 	AND ctrl_cmd_exec_code_name = #{ctrlCmdExecCodeName}


  		 	AND ctrl_kind_code = #{ctrlKindCode}


  		 	AND ctrl_cmd_code = #{ctrlCmdCode}

  		ORDER BY ctrlCmdExecCodeId

  		 	LIMIT #{start},#{end}


	  	SELECT ctrl_cmd_exec_code_id,
	  		ctrl_cmd_exec_code_name,
	  		ctrl_kind_code,
	  		ctrl_cmd_code,
	  		ctrl_exec_param,
	  		ctrl_exec_desc

		FROM ctrl_cmd_exec_code_info
  		WHERE 1=1	

  			 AND ctrl_cmd_exec_code_id = #{ctrlCmdExecCodeId}


  		 	AND ctrl_cmd_exec_code_name = #{ctrlCmdExecCodeName}


  		 	AND ctrl_cmd_exec_code_name LIKE CONCAT('%', #{execCodeName}, '%')


  		 	AND ctrl_kind_code = #{ctrlKindCode}


  		 	AND ctrl_cmd_code = #{ctrlCmdCode}
